/// Returns `true` when a message holds a tool call or a tool result.
fn has_tool_round(messages: &[aws_sdk_bedrockruntime::types::Message]) -> bool {
    messages.iter().any(|m| {
        m.content()
            .iter()
            .any(|b| matches!(b, ContentBlock::ToolUse(_) | ContentBlock::ToolResult(_)))
    })
}

